    payload: dict = {}
    if hard_delete is not _UNSET:
        payload["hard_delete"] = hard_delete
    if sudo is not _UNSET:
        payload["sudo"] = sudo
    return _ok(_get_client().request("DELETE", f"/users/{_enc(user_id)}", params=payload))


