    payload: dict = {}
    if sudo is not _UNSET:
        payload["sudo"] = sudo
    if i_dor_username:
        return _ok(_get_client().request("GET", f"/users/{_enc(i_dor_username)}/status", params=payload))
    return _ok(_get_client().request("GET", f"/user/status", params=payload))


